B.aQR=new A.eG("Sat\u0131n al\u0131nan krediler iade edilemez",null)
B.aUM=new A.j7("Kabul Edilebilir Kullan\u0131m",null)
B.aTn=new A.iJ("Uygulamay\u0131 yaln\u0131zca ki\u015fisel mekan analizi ama\xe7l\u0131 kullanabilirsiniz. A\u015fa\u011f\u0131daki davran\u0131\u015flar yasakt\u0131r:",null)
